return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ckb','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:02+00:00','po-revision-date'=>'2026-10-31T05:53:02+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'وەرگێڕانە ونبووەکانی ئەو پێوەکراو و ڕووکارانە پڕ دەکاتەوە کە پێشتر لەسەر ماڵپەڕەکەت دامەزراون.','Translations'=>'وەرگێڕانەکان','Babilim Settings'=>'ڕێکخستنەکانی Babilim','Settings'=>'ڕێکخستنەکان','You are not allowed to do this.'=>'ڕێگەپێدراو نیت ئەم کارە بکەیت.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'پێکهاتەی کەمتر هەڵبژێرە: لە هەر جارێکدا زیاترین %1$d کردار (تۆ %2$d هەڵبژاردووە).','That component is not installed on this site, so a translation cannot be requested for it.'=>'ئەم پێکهاتەیە لەسەر ئەم ماڵپەڕە دامەزراو نییە، بۆیە ناتوانرێت وەرگێڕان بۆی داوا بکرێت.','Already installed.'=>'پێشتر دامەزراوە.','Downloaded and installed.'=>'داگیرا و دامەزرا.','Babilim has not been enabled for this site yet.'=>'Babilim هێشتا بۆ ئەم ماڵپەڕە چالاک نەکراوە.','No build is available to download for this locale.'=>'هیچ بیلدێک بۆ داگرتن بەردەست نییە بۆ ئەم زمانی ناوچەییە.','Rolled back to the previous build.'=>'گەڕایەوە بۆ بیلدی پێشوو.','Rolled back and reported.'=>'گەڕایەوە و ڕاپۆرت کرا.','Rolled back, but the report could not be sent: %s'=>'گەڕایەوە، بەڵام ڕاپۆرتەکە نەتوانرا بنێردرێت: %s','Removed.'=>'لابرا.','Translation requested.'=>'وەرگێڕان داوا کرا.','This component was already uploaded. Babilim is checking it now.'=>'ئەم پێکهاتەیە پێشتر بارکراوە. Babilim ئێستا دەیپشکنێت.','Upload cancelled.'=>'بارکردن هەڵوەشێنرایەوە.','Upload complete — translation requested.'=>'بارکردن تەواو بوو — وەرگێڕان داوا کرا.','This component does not declare a version number, so a translation cannot be requested for it.'=>'ئەم پێکهاتەیە ژمارەی وەشان ڕانەگەیاندووە، بۆیە ناتوانرێت وەرگێڕان بۆی